from pathlib import Path
from collections import deque, defaultdict
from decimal import Decimal, InvalidOperation

folder = Path(__file__).resolve().parent
payload = json.loads((folder / 'prepared.json').read_text(encoding='utf-8'))
src, base = payload['source'], payload['base']
tasks = {t['id']: t for t in src['tasks']}
updated = {t['id']: t for t in payload['tasks']}
assert len(tasks) == len(src['tasks']) == len(updated)
edges = src['deps']
assert len(edges) == len({(e['project'], e['task'], e['depends_on']) for e in edges})
assert base['summary']['dep_count_raw'] == src['raw']
assert base['summary']['dep_count_unique'] == len(edges)
excluded_ids = {e['project'] for e in base['excluded']}
# Independently validate the IBL delay classification and cumulative sums.
delays = defaultdict(int)
for row in payload['delays']:
    value = Decimal(row['extra_days'])
    assert value.is_finite() and value >= 0 and value == value.to_integral_value()
    delays[row['task']] += int(value)
not_applied, applied = [], []
for i, extra in sorted(delays.items()):
    if i not in tasks:
        not_applied.append({'task': i, 'reason': 'unknown_task'})
    elif tasks[i]['project'] in excluded_ids:
        not_applied.append({'task': i, 'reason': 'excluded_project'})
    else:
        applied.append({'task': i, 'extra_days': extra, 'project': tasks[i]['project']})
assert applied == payload['applied']
assert not_applied == payload['not_applied']
for i, t in tasks.items():
    try:
        d = Decimal(str(t['duration']))
        bad = not d.is_finite() or d <= 0
    except InvalidOperation:
        bad = True
    assert bad == t['bad']
    if not bad:
        assert d == t['days']
    expected = t['days'] if t['project'] in excluded_ids else t['days'] + delays.get(i, 0)
    assert updated[i]['new_days'] == expected

by_project, by_edges = defaultdict(dict), defaultdict(list)
for i, t in tasks.items():
    by_project[t['project']][i] = t
for e in edges:
    assert e['project'] in by_project
    by_edges[e['project']].append(e)
new_rows, old_rows, excluded = [], [], []
checked_edges = 0
for p in sorted(by_project):
    ts, esrc = by_project[p], by_edges[p]
    bad = sum(t['bad'] for t in ts.values())
    missing = sum(e['task'] not in ts or e['depends_on'] not in ts for e in esrc)
    if bad or missing:
        excluded.append(dict(project=p, reason='bad_duration' if bad else 'missing_dep', detail_count=bad or missing))
        continue
    pred, succ = {i: [] for i in ts}, {i: [] for i in ts}
    for e in esrc:
        pred[e['task']].append(e['depends_on'])
        succ[e['depends_on']].append(e['task'])
    degree = {i: len(pred[i]) for i in ts}
    queue = deque(i for i in ts if not degree[i])
    order = []
    while queue:
        i = queue.popleft()
        order.append(i)
        for j in succ[i]:
            degree[j] -= 1
            if not degree[j]:
                queue.append(j)
    if len(order) != len(ts):
        excluded.append(dict(project=p, reason='cycle', detail_count=len(ts) - len(order)))
        continue
    checked_edges += len(esrc)
    for variant, target in ((False, old_rows), (True, new_rows)):
        duration = {i: updated[i]['new_days'] if variant else ts[i]['days'] for i in ts}
        starts, finishes, latest = {}, {}, {}
        for i in order:
            starts[i] = max((finishes[j] for j in pred[i]), default=0)
            finishes[i] = starts[i] + duration[i]
        project_end = max(finishes.values())
        for i in reversed(order):
            latest[i] = min((latest[j] for j in succ[i]), default=project_end) - duration[i]
        # Independent relaxation with a different traversal checks both passes.
        forward = {i: 0 for i in ts}
        for _ in range(len(ts)):
            next_values = {i: max((forward[j] + duration[j] for j in pred[i]), default=0) for i in reversed(list(ts))}
            if next_values == forward:
                break
            forward = next_values
        assert forward == starts
        remaining = {i: duration[i] for i in ts}
        for _ in range(len(ts)):
            next_values = {i: duration[i] + max((remaining[j] for j in succ[i]), default=0) for i in ts}
            if next_values == remaining:
                break
            remaining = next_values
        assert all(latest[i] == project_end - remaining[i] for i in ts)
        for i in sorted(ts):
            slack = latest[i] - starts[i]
            assert slack >= 0
            assert all(finishes[j] <= starts[i] for j in pred[i])
            target.append(dict(id=i, project=p, es=starts[i], ef=finishes[i], slack=slack, critical=slack == 0))
assert excluded == base['excluded']
assert sorted(old_rows, key=lambda r: r['id']) == base['tasks']
old_by_id = {r['id']: r for r in old_rows}
for r in new_rows:
    old = old_by_id[r['id']]
    assert r['es'] >= old['es'] and r['ef'] >= old['ef']
assert {r['id'] for r in new_rows} == {i for i, t in tasks.items() if t['project'] not in excluded_ids}
result = {'tasks': sorted(new_rows, key=lambda r: r['id']), 'checks': {'baseline_reproduced': True, 'delay_classification_checked': True, 'exclusions_unchanged': True, 'forward_backward_independent': True, 'nondecreasing_es_ef': True, 'tasks': len(new_rows), 'edges': checked_edges}}
(folder / 'graph.json').write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding='utf-8')
print(json.dumps(result['checks'], ensure_ascii=False))
